import pytest
from bibliofabric.exceptions import ConfigurationError, ValidationError

from ..conftest import load_fixture, load_fixture_json


def last_request(httpx_mock):
    return httpx_mock.get_requests()[-1]


def test_metadata_request_and_row(client, httpx_mock):
    httpx_mock.add_response(json=load_fixture_json("metadata.json"))
    rows = client.meta.metadata("doi:10.1007/978-1-4020-9632-7")
    request = last_request(httpx_mock)
    assert request.url.path == "/meta/v1/metadata/doi:10.1007/978-1-4020-9632-7"
    assert request.headers["accept"] == "application/json"
